'use client';

import Link from 'next/link';
import Image from 'next/image';
import { Auction } from '@/types';
import CountdownTimer from './CountdownTimer';
import { useState } from 'react';

interface Props {
  auction: Auction;
}

export default function AuctionCard({ auction }: Props) {
  const [currentPrice, setCurrentPrice] = useState(Number(auction.current_price));

  return (
    <Link
      href={`/auctions/${auction.id}`}
      className="block bg-white rounded-2xl shadow hover:shadow-md transition-shadow overflow-hidden"
    >
      {auction.image_url ? (
        <div className="relative h-48 w-full">
          <Image src={auction.image_url} alt={auction.title} fill className="object-cover" />
        </div>
      ) : (
        <div className="h-48 bg-indigo-50 flex items-center justify-center text-indigo-200 text-6xl">
          🏷
        </div>
      )}

      <div className="p-4 space-y-2">
        <h3 className="font-semibold text-gray-900 truncate">{auction.title}</h3>
        <p className="text-xs text-gray-500">par {auction.user?.name}</p>

        <div className="flex items-center justify-between mt-3">
          <div>
            <p className="text-xs text-gray-400">Prix actuel</p>
            <p className="text-lg font-bold text-indigo-600">{currentPrice.toFixed(2)} €</p>
          </div>
          <div className="text-right">
            <p className="text-xs text-gray-400">Temps restant</p>
            <CountdownTimer endAt={auction.end_at} />
          </div>
        </div>

        {auction.bids_count !== undefined && (
          <p className="text-xs text-gray-400">{auction.bids_count} offre(s)</p>
        )}
      </div>
    </Link>
  );
}
